public long minMoves(int n) {
    return (1L << n) - 1; // 2^n - 1
}

public int towerOfHanoi(int n, char from, char aux, char to) {
    if (n == 0) return 0;
    int moves = 0;
    moves += towerOfHanoi(n - 1, from, to, aux); // park n-1 on aux (to is helper)
    System.out.println("Move disk " + n + " from " + from + " to " + to);
    moves += 1;
    moves += towerOfHanoi(n - 1, aux, from, to); // bring n-1 to target (from is helper)
    return moves;
}

